<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';import {shanghaiDateTimeText} from '../../utils/shanghai-date.js';
const router=useRouter(),rows=ref([]),search=ref(''),loading=ref(false);let sequence=0;
const filtered=computed(()=>rows.value.filter(row=>[row.vendor_code,row.payload.card.title,row.shop_name].some(value=>String(value||'').toLowerCase().includes(search.value.trim().toLowerCase()))));
async function load(){const id=++sequence,scope=currentApiCacheScope();loading.value=true;try{const r=await apiClient.get('/api/wb/workbench-drafts',{noCache:true});if(id===sequence&&scope===currentApiCacheScope())rows.value=r.rows||[];}catch(e){if(id===sequence&&scope===currentApiCacheScope())ElMessage.error(e.message);}finally{if(id===sequence)loading.value=false;}}
function reset(){rows.value=[];search.value='';load();}
onMounted(()=>{load();window.addEventListener('erp:auth-scope-changed',reset);});onBeforeUnmount(()=>{sequence++;window.removeEventListener('erp:auth-scope-changed',reset);});
</script>
<template><div class="wb-drafts"><div class="draft-tools"><el-input v-model="search" clearable placeholder="搜索货号、商品或店铺"/><el-button :loading="loading" @click="load">刷新</el-button></div><el-table :data="filtered" v-loading="loading" border stripe empty-text="暂无 WB 商品草稿"><el-table-column prop="vendor_code" label="货号" min-width="180"/><el-table-column label="商品" min-width="280"><template #default="{row}">{{row.payload.card.title}}</template></el-table-column><el-table-column prop="shop_name" label="店铺" min-width="150"/><el-table-column label="变体数" width="90"><template #default="{row}">{{row.payload.variants?.length||1}}</template></el-table-column><el-table-column label="售价（CNY）" width="130"><template #default="{row}">{{row.payload.card.sizes[0]?.price??'待填写'}}</template></el-table-column><el-table-column label="更新（北京）" width="180"><template #default="{row}">{{shanghaiDateTimeText(row.updated_at,{assumeUtcWhenNaive:true})}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="router.push({path:'/listing-automation',query:{platform:'wb',wbDraftId:String(row.id)}})">编辑草稿</el-button></template></el-table-column></el-table></div></template>
<style scoped>.draft-tools{display:flex;gap:8px;margin-bottom:12px}.draft-tools>.el-input{max-width:360px}</style>
